export const LIMIT=60,TENURE=6;
export const oathTypes={anchor:'固定城市位置',food:'守护粮食储备',peace:'守护社会安定',trade:'守护贸易繁荣',ecology:'守护生态'};
export const metricNames={food:'粮食',peace:'安定',trade:'繁荣',ecology:'生态'};
export const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const clamp=n=>Math.max(0,Math.min(100,n));
export function initial(){const seeds=[['ember','余烬城',180,180,2.3,1.1,'炉火与工艺'],['grove','苔原城',390,145,-1.4,2.2,'林地与灵木'],['tide','潮汐城',710,210,-2.1,-1.5,'航海与贸易'],['archive','旧誓城',245,420,1.8,-1.9,'记忆与学识'],['grain','麦穗城',550,405,-2.2,1.1,'农田与粮仓'],['mist','雾隐城',795,450,-1.7,-1.6,'边境与隐秘']];return {turn:0,current:'ember',visited:['ember'],ended:false,ending:null,events:[],history:[{turn:0,kind:'开端',text:'你成为造物主的使者，抵达余烬城。每座城市都在漂移，唯有誓约可能留下不变之物。'}],cities:seeds.map(([id,name,x,y,vx,vy,lore],i)=>({id,name,x,y,origin:{x,y},vx,vy,lore,food:50+i*2,peace:60-i*2,trade:42+i*3,ecology:70-i*4,oath:null,visits:i===0?1:0,eventSeen:[]}))};}
export function nearest(s,id=s.current){const c=s.cities.find(c=>c.id===id);return s.cities.filter(c=>c.id!==id).sort((a,b)=>distance(c,a)-distance(c,b)||a.id.localeCompare(b.id))[0];}
export function connections(s){return s.cities.flatMap((a,i)=>s.cities.slice(i+1).map(b=>({a:a.id,b:b.id,distance:Math.round(distance(a,b)),type:distance(a,b)<180?'邻接':distance(a,b)<330?'贸易':'隔绝'})));}
export function parseOath(text){text=text.trim();if(!text||text.length>160)throw new Error('请填写1–160字的誓约。');if(/毁灭|杀光|无限|全能|永生|无敌/.test(text))throw new Error('请限定一个可守护的事物。');
 const matches=[['anchor',/位置|原地|不.{0,3}漂移|停止.{0,3}移动|不.{0,3}移动|坐标/],['food',/粮|饥饿|饥荒|食物|饱腹/],['peace',/和平|交战|战争|安定|冲突|争斗/],['trade',/贸易|繁荣|商贸|经济/],['ecology',/生态|森林|树木|自然|林地/]].filter(([,r])=>r.test(text));if(matches.length!==1)throw new Error(matches.length?'每城只能固定一项，请缩小誓约范围。':'本地模拟不能理解此誓约，请明确包含位置、粮食、和平、繁荣或生态。');
 const type=matches[0][0],rules={anchor:['peace',35,'安定≥35；每轮消耗1繁荣'],food:['trade',30,'繁荣≥30；每轮消耗1繁荣'],peace:['food',25,'粮食≥25；每轮消耗1粮食'],trade:['peace',40,'安定≥40；每轮消耗1生态'],ecology:['food',30,'粮食≥30；每轮消耗1繁荣']};const [metric,min,explanation]=rules[type];return {text,type,condition:{metric,min},explanation,source:'本地模拟'};}
export function oathActive(c){return !!c.oath&&c[c.oath.condition.metric]>=c.oath.condition.min;}
export function setOath(state,oath){if(state.ended)throw new Error('世界已结算，请重新开始。');if(!oathTypes[oath.type]||!metricNames[oath.condition?.metric]||!Number.isFinite(oath.condition.min)||oath.condition.min<0||oath.condition.min>100||typeof oath.text!=='string'||!oath.text.trim()||oath.text.length>160)throw new Error('誓约判定无效');const s=structuredClone(state),c=s.cities.find(c=>c.id===s.current);c.oath={...oath,anchor:{x:c.x,y:c.y},createdAt:s.turn};s.history.push({turn:s.turn,kind:'立誓',city:c.id,text:`${c.name}：「${oath.text}」→${oathTypes[oath.type]}。实行条件：${oath.explanation}。离任后保留，不推进时间。`});return s;}
export const citizenEvents=[
 {id:'hunger',name:'粮仓告急',condition:'粮食<25',when:c=>c.food<25,effect:{peace:-3},text:'居民为最后的口粮争执。'},
 {id:'unrest',name:'广场请愿',condition:'安定<35',when:c=>c.peace<35,effect:{trade:-3},text:'居民要求城主解释漂移和分配制度。'},
 {id:'seed',name:'归林的幼苗',condition:'生态≥70',when:c=>c.ecology>=70,effect:{food:3},text:'林地向居民赠予新的种子。'},
 {id:'market',name:'流动集市',condition:'至少一城进入贸易或邻接范围',when:(c,s)=>s.cities.some(b=>b.id!==c.id&&distance(c,b)<330),effect:{trade:3},text:'漂移缩短路程，商贩重新搭起集市。'},
 {id:'refugees',name:'漂流的旅人',condition:'最近城市安定<40',when:(c,s)=>nearest(s,c.id).peace<40,effect:{food:-2,peace:1},text:'邻城旅人带来动荡的消息，居民分出粮食接待他们。'},
 {id:'feast',name:'共享晚餐',condition:'粮食≥65且安定≥60',when:c=>c.food>=65&&c.peace>=60,effect:{food:-2,peace:3},text:'居民摆出长桌，与陌生人分享晚餐。'},
 {id:'craft',name:'工匠学徒',condition:'繁荣≥60',when:c=>c.trade>=60,effect:{trade:2,ecology:-1},text:'工匠扩大生产，也消耗了一片林地。'},
 {id:'isolation',name:'失联的信使',condition:'最近城市距离>330',when:(c,s)=>distance(c,nearest(s,c.id))>330,effect:{peace:-2},text:'信使没能返回，居民意识到城市正在远离世界。'},
 {id:'torch',name:'火炬下的守夜人',condition:'本城誓约满足实行条件',when:c=>oathActive(c),effect:{peace:1},text:'居民轮流守护火炬，确认承诺仍然有效。'},
 {id:'watch',name:'街巷守望',condition:'没有其他未发生事件满足条件',when:()=>true,effect:{},repeat:true,text:'居民记录地平线的变化，等待使者的决定。'}];
function change(c,delta){for(const [k,v] of Object.entries(delta))c[k]=clamp(c[k]+v);}
export function enforceOaths(s,before){for(const c of s.cities){const old=before.find(b=>b.id===c.id);if(!old||!oathActive(old))continue;if(c.oath?.type==='anchor'){c.x=old.oath.anchor.x;c.y=old.oath.anchor.y;}else {const k=old.oath.type;c[k]=Math.max(c[k],old[k]);}}}
export function advance(state,action){if(state.ended)throw new Error('世界已结算。');if(!['farm','mediate','build','restore','observe'].includes(action))throw new Error('未知行动');const s=structuredClone(state),before=structuredClone(s.cities),oldLinks=connections(s),current=s.cities.find(c=>c.id===s.current);
 const effects={farm:{food:7,ecology:-2},mediate:{peace:6,food:-1},build:{trade:6,ecology:-3},restore:{ecology:6,trade:-2},observe:{}};change(current,effects[action]);s.turn++;s.history.push({turn:s.turn,kind:'行动',city:current.id,text:`你在${current.name}${{farm:'组织耕种',mediate:'调解争端',build:'建设集市',restore:'修复林地',observe:'观察世界'}[action]}。`});
 for(const c of s.cities){const old=before.find(b=>b.id===c.id);if(!oathActive(old)||c.oath.type!=='anchor'){c.x+=c.vx+Math.sin(s.turn/5+c.origin.x)*1.1;c.y+=c.vy+Math.cos(s.turn/6+c.origin.y)*1.1;if(c.x<65||c.x>935){c.vx*=-1;c.x=Math.max(65,Math.min(935,c.x));}if(c.y<65||c.y>535){c.vy*=-1;c.y=Math.max(65,Math.min(535,c.y));}}change(c,{food:-1});if(oathActive(old))change(c,c.oath.type==='peace'?{food:-1}:c.oath.type==='trade'?{ecology:-1}:{trade:-1});}
 s.links=connections(s);s.interactions=[];for(const pair of s.links){const a=s.cities.find(c=>c.id===pair.a),b=s.cities.find(c=>c.id===pair.b),old=oldLinks.find(p=>p.a===pair.a&&p.b===pair.b);let note='';if(pair.type==='邻接'){if(Math.min(a.peace,b.peace)<40){change(a,{peace:-1});change(b,{peace:-1});note='边界摩擦：邻城因不安定互相猜疑';}else{change(a,{food:1,trade:1});change(b,{food:1,trade:1});note='邻接合作：交换粮食与工艺';}}else if(pair.type==='贸易'){change(a,{trade:1});change(b,{trade:1});note='商路互通：距离允许商队往来';}if(old.type!==pair.type)s.history.push({turn:s.turn,kind:'距离变化',text:`${a.name}↔${b.name}：${old.type}→${pair.type}（${old.distance}→${pair.distance}）。${note||'旧商路断开。'}`});if(note)s.interactions.push(`${a.name}↔${b.name}，距离${pair.distance}：${note}。`);}
 for(const c of s.cities)if(distance(c,nearest(s,c.id))>330)change(c,{trade:-1,peace:-1});const e=citizenEvents.find(e=>(e.repeat||!current.eventSeen.includes(e.id))&&e.when(current,s));if(!e.repeat)current.eventSeen.push(e.id);change(current,e.effect);s.events=[{name:e.name,city:current.name,text:e.text,condition:e.condition,effect:e.effect}];s.history.push({turn:s.turn,kind:'市民事件',city:current.id,text:`${current.name}·${e.name}：${e.text} 触发条件：${e.condition}。`});enforceOaths(s,before);s.history.push({turn:s.turn,kind:'世界快照',cities:structuredClone(s.cities),text:`第${s.turn}轮世界状态已记录。`});
 if(s.turn===LIMIT){s.ended=true;s.ending=localEnding(s);}else if(s.turn%TENURE===0){const next=nearest(s);s.current=next.id;next.visits++;if(!s.visited.includes(next.id))s.visited.push(next.id);s.history.push({turn:s.turn,kind:'迁城',text:`六轮任期结束：离开${current.name}，前往最近的${next.name}（距离${Math.round(distance(current,next))}）。旧城誓约继续生效。`});}return s;}
export function localEnding(s){const avg=k=>Math.round(s.cities.reduce((n,c)=>n+c[k],0)/s.cities.length),actions=s.history.filter(h=>h.kind==='行动'),vows=s.history.filter(h=>h.kind==='立誓'),values={food:avg('food'),peace:avg('peace'),trade:avg('trade'),ecology:avg('ecology')};const title=values.food<25?'饥荒中的漂流':values.peace<40?'分裂的群岛':values.ecology<35?'繁荣的代价':values.trade>=65?'流动的共同体':'未完成的世界';return {title,source:'本地模拟',text:`六十轮过去，城市仍在移动。你完成${actions.length}次行动，留下${vows.length}次誓约记录，亲历${s.visited.length}座城市。平均粮食${values.food}、安定${values.peace}、繁荣${values.trade}、生态${values.ecology}。${values.ecology<35?'建设与耕种消耗的林地成为未来的代价。':`你留下的${vows.length}次誓约与${actions.filter(a=>a.text.includes('修复林地')).length}次林地修复，是这段历史中可追溯的守护行动。`}${values.food<25?'许多城市仍在寻找足够的食物。':'粮食储备决定了城市能否继续等待下一个邻居。'}`,values,evidence:[...s.history.filter(h=>h.kind==='立誓').slice(0,6),...s.history.filter(h=>h.kind==='迁城').slice(-3),...s.history.filter(h=>h.kind==='距离变化').slice(-3),...s.history.filter(h=>h.kind==='行动').slice(-3)].map(h=>`第${h.turn}轮：${h.text}`)};}
export function applyAiTurn(state,data,before){const s=structuredClone(state);if(typeof data.summary!=='string'||data.summary.length>1500||!Array.isArray(data.effects)||data.effects.length>6)throw new Error('AI响应格式无效');if(new Set(data.effects.map(e=>e.cityId)).size!==data.effects.length)throw new Error('AI不能对同一城市重复累计影响');for(const effect of data.effects){const c=s.cities.find(c=>c.id===effect.cityId);if(!c||typeof effect.reason!=='string'||effect.reason.length>300)throw new Error('AI城市影响无效');const delta={};for(const [k,v]of Object.entries(effect.delta||{})){if(!metricNames[k]||!Number.isInteger(v)||Math.abs(v)>3)throw new Error('AI影响超出允许范围');delta[k]=v;}change(c,delta);s.history.push({turn:s.turn,kind:'AI影响',city:c.id,text:`${c.name}：${effect.reason}；${Object.entries(delta).map(([k,v])=>`${metricNames[k]} ${v>0?'+':''}${v}`).join('，')}`});}enforceOaths(s,before.cities);s.history.push({turn:s.turn,kind:'AI判定',text:data.summary});s.history.push({turn:s.turn,kind:'AI后快照',cities:structuredClone(s.cities),text:'真实AI影响结算后的世界状态。'});if(s.ended)s.ending=localEnding(s);return s;}
